import React from 'react';
import '../styles/components.css';

function FileList({ files, selectedFiles, onSelectFile, onDeleteFile }) {
  if (!files || files.length === 0) {
    return <p className="info-text">No files available</p>;
  }

  return (
    <div className="file-list">
      {files.map((file) => (
        <div key={file.id || file.name} className="file-item"> {/* ✅ AÑADIR KEY ÚNICO */}
          <input
            type="checkbox"
            id={`file-${file.id}`}
            checked={selectedFiles.includes(file.id)}
            onChange={() => onSelectFile(file.id)}
          />
          <label htmlFor={`file-${file.id}`} className="file-name">
            {file.name}
          </label>
          <button 
            className="delete-button"
            onClick={() => onDeleteFile(file.id)}
            title="Delete file"
          >
            🗑️
          </button>
        </div>
      ))}
    </div>
  );
}

export default FileList;
